SUPPLEMENT_COLUMNS = (
    ("Reaction_Type", None, "MSR", "APRM_ROWS"),
    ("Reactor_Mode", "REACTOR_MODE", "", None),
    ("Reaction_Time_h", "REACTION_TIME_H", "", None),
    ("GHSV_h_inv", "GHSV_H_INV", "", None),
    ("LHSV_h_inv", "LHSV_H_INV", "", None),
    ("Initial_Pressure_bar", "INITIAL_PRESSURE_BAR", "", None),
    ("Reaction_Cycle", "REACTION_CYCLE", "", None),
    ("Pressure_Basis", "PRESSURE_BASIS", "", None),
    ("_version_dir", "VERSION_DIR", "", None),
)


def apply_embedded_selection(raw: pd.DataFrame) -> pd.DataFrame:
    """Materialize the published selection columns on the raw frame."""
    n = len(raw)
    for col, _, default, _ in SUPPLEMENT_COLUMNS:
        raw[col] = default if col == "Reaction_Type" else ""
    aprm = set(globals()["APRM_ROWS"])
    for col, table, default, _ in SUPPLEMENT_COLUMNS:
        if table is None:
            values = ["APRM" if i in aprm else default for i in range(n)]
            raw[col] = values
        else:
            for i, v in globals()[table].items():
                raw.iat[i, raw.columns.get_loc(col)] = v
    rid = [str(i) for i in range(n)]
    for i, v in RAW_ROW_ID_OVERRIDE.items():
        rid[i] = v
    raw["raw_row_id"] = rid
    return raw


# ── Feature contract (v6_scientific_features_3, 31 features) ────────────────
# All temperatures are represented in degrees Celsius only.
FEATURE_SCHEMA_VERSION = "v6_scientific_features_3"

