# ── Tabulated element/support properties (CRC Handbook, 97th ed.; Pauling
#    electronegativity, Shannon ionic radius, IUPAC 2013 atomic weight) ─────
# Tuple layout: (electronegativity, ionic_radius_A, atomic_mass, first_IE_eV)
PROMOTER_PROPS = {
    "Ce": (1.12, 1.01, 140.12, 5.539),
    "Co": (1.88, 0.745, 58.93, 7.881),
    "Cu": (1.90, 0.73, 63.55, 7.726),
    "In": (1.78, 0.80, 114.82, 5.786),
    "La": (1.10, 1.032, 138.91, 5.577),
    "Mg": (1.31, 0.72, 24.31, 7.646),
    "Mo": (2.16, 0.59, 95.95, 7.092),
    "Pd": (2.20, 0.86, 106.42, 8.337),
    "Pt": (2.28, 0.80, 195.08, 9.000),
    "Sn": (1.96, 0.69, 118.71, 7.344),
    "Zn": (1.65, 0.74, 65.38, 9.394),
}

# Tuple layout: (support_type, acid_base, reducible)
SUPPORT_PROPS = {
    "Al2O3": ("oxide", 2, 0), "Al2O4": ("oxide", 2, 0),
    "CN": ("nitride", 0, 0), "h-BN": ("nitride", 0, 0),
    "CNTs": ("carbon", 0, 0), "Carbon": ("carbon", 0, 0),
    "CeO2": ("oxide", 3, 1), "Cement-Clay": ("composite", 0, 0),
    "LDH": ("ldh", 3, 0), "MgAl": ("ldh", 3, 0),
    "MgO": ("oxide", 3, 0), "Mo2C": ("carbide", 0, 1),
    "NaF": ("salt", 0, 0), "SnO2": ("oxide", 2, 1),
    "TiO2": ("oxide", 2, 1), "TiO2-CeO2": ("composite", 2, 1),
    "ZnO": ("oxide", 2, 1), "ZrO2": ("oxide", 2, 1),
    "Perovskite": ("oxide", 2, 1), "Spinel": ("oxide", 2, 1),
    "Other": ("unknown", 0, 0), "Unknown": ("unknown", 0, 0),
}


# ── Composition parsing (free-text Alloy_Ratio -> mole fractions) ────────────
ELEMENT_PROPS = dict(PROMOTER_PROPS)
ELEMENT_PROPS.update({
    "Ni": (1.91, 0.69, 58.69, 7.640),
    "Al": (1.61, 0.535, 26.98, 5.986),
    "Mn": (1.55, 0.83, 54.94, 7.434),
    "Cr": (1.66, 0.615, 52.00, 6.767),
    "Au": (2.54, 1.37, 196.97, 9.226),
    "Rh": (2.28, 0.665, 102.91, 7.459),
    "Ir": (2.20, 0.625, 192.22, 8.967),
})

NON_METAL = {"O", "C", "N", "H", "S", "P", "F", "Cl", "Br", "I"}
KNOWN = set(ELEMENT_PROPS)

_PAIR = re.compile(r"([A-Z][a-z]?)\s*[:=]\s*(\d+(?:\.\d+)?)")
_SLASH = re.compile(r"([A-Z][a-z]?)\s*:\s*([A-Z][a-z]?)\s*=\s*(\d+(?:\.\d+)?)\s*/\s*(\d+(?:\.\d+)?)")
_COLON_MULTI = re.compile(r"([A-Z][a-z]?(?:\s*:\s*[A-Z][a-z]?)+)\s*=\s*([\d.:\s]+)")


def _strip_prose(text: str) -> str:
    """Drop parenthesised prose so letters inside it are not read as elements."""
    return re.sub(r"\([^)]*\)", " ", text)


def _basis(text: str) -> str:
    low = text.lower()
    if "atom" in low or "atomic" in low:
        return "atomic_pct"
    if "mol" in low and "molar" not in low and "mol%" in low:
        return "atomic_pct"
    if "molar" in low:
        return "molar"
    if "weight" in low or "mass" in low or "wt" in low:
        return "weight"
    return "bare"


def parse_alloy_ratio(value: object):
    """Return (fractions, basis) with fractions a dict of metal -> mole fraction.

    Returns (None, reason) when the text carries no usable composition.
    """
    if not isinstance(value, str) or not value.strip():
        return None, "empty"
    text = value.strip()
    basis = _basis(text)
    body = _strip_prose(text)
    raw: dict[str, float] = {}

    def put(elem: str, val: float) -> None:
        if elem in KNOWN and val > 0:
            raw[elem] = raw.get(elem, 0.0) + val

    # Three mutually exclusive shapes.  They must not be combined: on
    # "Cu:Ni = 4:1" the pair pattern would also read "Ni = 4" and add it to the
    # Ni already taken from the ratio, inflating the fraction.
    m = _SLASH.search(body)
    if m:
        put(m.group(1), float(m.group(3)))
        put(m.group(2), float(m.group(4)))
    else:
        structured = False
        for m in _COLON_MULTI.finditer(body):
            elems = [e.strip() for e in m.group(1).split(":")]
            vals = [v for v in m.group(2).strip().split(":") if v.strip()]
            if len(elems) == len(vals):
                structured = True
                for e, v in zip(elems, vals):
                    try:
                        put(e, float(v))
                    except ValueError:
                        structured = False
        if not structured:
            for m in _PAIR.finditer(body):
                put(m.group(1), float(m.group(2)))

    if len(raw) < 2:
        return None, "fewer than two elements parsed"

    metals = {e: v for e, v in raw.items() if e not in NON_METAL}
    if len(metals) < 2:
        return None, "fewer than two metals"

    if basis == "weight":
        # mass -> moles
        mol = {}
        for e, v in metals.items():
            mass = ELEMENT_PROPS[e][2]
            mol[e] = v / mass
    else:
        mol = dict(metals)

    total = sum(mol.values())
    if total <= 0:
        return None, "non-positive total"
    return {e: v / total for e, v in mol.items()}, basis


def build_composition_features(value: object) -> dict:
    """Derive the model-facing descriptor block from one Alloy_Ratio string."""
    nan = float("nan")
    out = {"comp_ni_fraction": nan, "comp_other_fraction": nan,
           "comp_electronegativity_mean": nan, "comp_electronegativity_range": nan,
           "comp_ni_contrast": nan, "comp_measured": 0.0, "comp_basis": "none"}
    frac, basis = parse_alloy_ratio(value)
    if frac is None:
        return out
    props = {e: ELEMENT_PROPS[e] for e in frac}
    chi = {e: props[e][0] for e in frac}
    out["comp_ni_fraction"] = frac.get("Ni", 0.0)
    out["comp_other_fraction"] = 1.0 - frac.get("Ni", 0.0)
    out["comp_electronegativity_mean"] = sum(frac[e] * chi[e] for e in frac)
    out["comp_electronegativity_range"] = max(chi.values()) - min(chi.values())
    others = {e: frac[e] for e in frac if e != "Ni"}
    if others and "Ni" in frac:
        w = sum(others.values())
        mean_other = sum(others[e] * chi[e] for e in others) / w
        out["comp_ni_contrast"] = abs(chi["Ni"] - mean_other)
    out["comp_measured"] = 1.0
    out["comp_basis"] = basis
    return out


COMPOSITION_NUMERIC = ["comp_ni_fraction", "comp_other_fraction",
                       "comp_electronegativity_mean", "comp_electronegativity_range",
                       "comp_ni_contrast"]
COMPOSITION_BINARY = ["comp_measured"]
COMPOSITION_AUDIT = ["comp_basis"]


# ── Duplicate folding (embedded, evidence-confirmed pairs) ──────────────────
def fold_confirmed(df, feature_columns, target):
    """Fold the embedded evidence-confirmed duplicate representations.

    Pair order is the published approval order and is order-sensitive: when
    several confirmed duplicates of one measurement captured a field the
    representative missed, the later approved pair fills the remaining gap.
    """
    df = df.copy()
    mapping = {}
    for child, parent in FOLD_PAIRS:
        if child == parent or child in mapping:
            raise ValueError("Invalid duplicate relationship identity")
        mapping[child] = parent
    for child, parent in mapping.items():
        if parent in mapping:
            raise ValueError("Duplicate representatives must not form chains or cycles")
    pos_to_idx = {p: i for i, p in enumerate(ELIGIBLE_ROWS)}
    for child, parent in mapping.items():
        a = df.iloc[pos_to_idx[child]]
        for col in feature_columns + [target]:
            av, bv = a[col], df.iloc[pos_to_idx[parent]][col]
            if pd.isna(av) and pd.isna(bv):
                continue
            if pd.isna(av) or pd.isna(bv):
                if pd.isna(bv):
                    df.iloc[pos_to_idx[parent], df.columns.get_loc(col)] = av
                continue
    child_idx = {pos_to_idx[c] for c in mapping}
    groups = {i: [i] for i in range(len(df)) if i not in child_idx}
    for child, parent in mapping.items():
        groups[pos_to_idx[parent]].append(pos_to_idx[child])
    order = sorted(groups)
    output = df.iloc[order].copy()
    output["Original_Record_IDs"] = [json.dumps(sorted("row-%d" % ELIGIBLE_ROWS[i] for i in groups[i]))
                                     for i in order]
    output["Original_Row_IDs"] = [json.dumps([str(ELIGIBLE_ROWS[i]) for i in sorted(groups[i])])
                                  for i in order]
    return output.reset_index(drop=True)


# ── Main cleaning pipeline ───────────────────────────────────────────────────
def prepare(source, output):
    source, output = Path(source).resolve(), Path(output).resolve()
    sha = hashlib.sha256(source.read_bytes()).hexdigest()
    if sha != DATASET_SHA256:
        raise ValueError(
            "dataset_all.csv does not match the published selection dataset "
            f"(expected {DATASET_SHA256[:16]}..., got {sha[:16]}...).  A changed "
            "dataset requires re-establishing the modeling selection.")
    raw = pd.read_csv(source, dtype=str, keep_default_na=False)
    raw = apply_embedded_selection(raw)
    df = raw.iloc[ELIGIBLE_ROWS].copy().replace("", np.nan)
    if len(df) < 10:
        raise ValueError("Too few selected records for five-fold regression")
    if not df.Reaction_Type.isin(["MSR", "APRM"]).all():
        raise ValueError("Unresolved reaction type in model input")
    target = TARGET
    _numeric_coercion = sorted(set(RAW_NUMERIC_FEATURES) | {
        target, "GHSV_mL_g_h", "WHSV_h_inv", "GHSV_h_inv", "LHSV_h_inv",
        "Residence_Time_s", "Initial_MeOH_Concentration_mol_L",
        "Catalyst_Concentration_g_L", "Initial_Pressure_bar",
        "Reaction_Cycle", "Initial_MeOH_wt_pct"})
    for col in _numeric_coercion:
        if col in df:
            parsed = pd.to_numeric(df[col], errors="coerce")
            if (df[col].notna() & parsed.isna()).any():
                raise ValueError(f"Unparsed numeric value or interval in {col}; source review required")
            df[col] = parsed
    if df[target].isna().any() or not df[target].between(0, 100).all() or df.Reaction_Temp_C.isna().any():
        raise ValueError("Selected model data has invalid target/temperature")
    df["Paper_ID"] = df.Source_File.map(PAPER_MAP)
    if df.Paper_ID.isna().any() or df.Paper_ID.eq("").any():
        raise ValueError("Missing reviewed paper identity")
    df["Catalyst_Key"] = df.Catalyst.str.strip().str.lower()
    for col in ("Support", "Promoter_Metal", "Metal_Loading_Method"):
        df[col] = df[col].map(lambda v: v.strip() if isinstance(v, str) else v)
    df["Catalyst_Label_Ni_Value"] = np.nan
    for source_col, result_col in (("GHSV_mL_g_h", "GHSV_log"), ("WHSV_h_inv", "WHSV_log")):
        if (df[source_col].dropna() < 0).any():
            raise ValueError("Negative space velocity needs source review")
        df[result_col] = np.log1p(df[source_col])
    for source_col, result_col in (("GHSV_h_inv", "GHSV_h_inv_log"),
                                   ("LHSV_h_inv", "LHSV_h_inv_log"),
                                   ("TOS_h", "TOS_log"),
                                   ("Reaction_Time_h", "Reaction_Time_log"),
                                   ("Residence_Time_s", "Residence_Time_log")):
        if source_col not in df:
            df[source_col] = np.nan
        if (df[source_col].dropna() < 0).any():
            raise ValueError(f"Negative physical feature needs source review: {source_col}")
        df[result_col] = np.log1p(df[source_col])
    df["Reaction_Temp_K"] = df.Reaction_Temp_C + 273.15
    if (df.Reaction_Temp_K <= 0).any():
        raise ValueError("Non-physical absolute reaction temperature")
    df["Inv_Reaction_Temp_K"] = 1000.0 / df.Reaction_Temp_K
    df["calc_reduc_temp_diff"] = df.Calcination_Temp_C - df.Reduction_Temp_C
    df["total_treatment_time_h"] = df[["Calcination_Time_h", "Reduction_Time_h", "Dry_Time_h"]].sum(axis=1, min_count=3)
    absent = df.Promoter_Metal.fillna("").str.lower().isin(["none", "no promoter", "无助剂"])
    df["has_promoter"] = np.where(absent, 0.0, np.where(df.Promoter_Metal.notna(), 1.0, np.nan))
    df["effective_promoter_loading_wt"] = df["Promoter_Loading_wt%"]
    df.loc[absent & df["effective_promoter_loading_wt"].isna(), "effective_promoter_loading_wt"] = 0.0
    df["total_metal_loading_wt"] = df[["Ni_Loading_wt%", "effective_promoter_loading_wt"]].sum(axis=1, min_count=2)
    df["promoter_to_ni_ratio"] = np.where(
        df["Ni_Loading_wt%"].gt(0),
        df["effective_promoter_loading_wt"] / df["Ni_Loading_wt%"],
        np.nan,
    )
    props = df.Promoter_Metal.fillna("").str.split(",").str[0].map(PROMOTER_PROPS)
    for i, col in enumerate(("prom_electronegativity", "prom_ionic_radius", "prom_atomic_mass", "prom_first_ionization")):
        df[col] = props.map(lambda p: p[i] if isinstance(p, tuple) else np.nan)
    df["prom_missing"] = props.isna().astype(int)
    support = df.Support.map(SUPPORT_PROPS)
    for i, col in enumerate(("support_type", "support_acid_base", "support_reducible")):
        df[col] = support.map(lambda p: p[i] if isinstance(p, tuple) else np.nan)
    df["Reaction_Context"] = df.Reaction_Type.fillna("Unknown") + "|" + df.Reactor_Mode.fillna("Unknown")
    time_flags = pd.DataFrame({
        "batch": df.Reaction_Time_h.notna(),
        "residence": df.Residence_Time_s.notna(),
        "tos": df.TOS_h.notna(),
    })
    df["Operation_Time_Type"] = np.select(
        [time_flags.sum(axis=1).eq(0), time_flags.sum(axis=1).gt(1), time_flags.batch,
         time_flags.residence, time_flags.tos],
        ["unreported", "multiple", "reaction_time", "residence_time", "time_on_stream"],
        default="unreported",
    )
    df["binding_matched"] = 1
    df["model_eligible"] = "true"
    df["record_id"] = ["row-%d" % p for p in ELIGIBLE_ROWS]
    df["original_row_sha256"] = ""
    if "Residence_Time_s" not in df:
        df["Residence_Time_s"] = np.nan
    if "Initial_MeOH_Concentration_mol_L" not in df:
        df["Initial_MeOH_Concentration_mol_L"] = np.nan
    if "Catalyst_Concentration_g_L" not in df:
        df["Catalyst_Concentration_g_L"] = np.nan
    if "Initial_MeOH_wt_pct" not in df:
        df["Initial_MeOH_wt_pct"] = np.nan
    if "_flag_conv_gt100" not in df:
        df["_flag_conv_gt100"] = ""
    df["Original_Row_IDs"] = df.raw_row_id.astype(str)
    df = fold_confirmed(df, MODEL_FEATURES, target)
    for col in ("Precursor_Family", "Support_Prep_Method"):
        df[col] = df[col].fillna("Unknown")

    _comp = pd.DataFrame([build_composition_features(v) for v in df.get("Alloy_Ratio", pd.Series([""] * len(df)))],
                         index=df.index)
    df = pd.concat([df, _comp[COMPOSITION_NUMERIC + COMPOSITION_BINARY]], axis=1)
    df["comp_basis"] = _comp["comp_basis"].values

    df = df.reset_index(drop=True)
    df.insert(0, "row_id", np.arange(len(df)))
    if not set(MODEL_FEATURES).issubset(df):
        raise ValueError("Incomplete feature schema")
    leaked = FORBIDDEN_MODEL_FEATURES.intersection(MODEL_FEATURES)
    if leaked:
        raise ValueError(f"Audit metadata leaked into feature schema: {sorted(leaked)}")
    promoted = set(COMPOSITION_NUMERIC + COMPOSITION_BINARY + COMPOSITION_AUDIT).intersection(MODEL_FEATURES)
    if promoted:
        raise ValueError(f"Paper-correlated composition columns promoted to model features: {sorted(promoted)}")
    output.mkdir(parents=True, exist_ok=True)
    path = output / "ni_model_primary.csv"
    df.to_csv(path, index=False, encoding="utf-8-sig")
    info = dict(version="verified_v6", feature_schema_version=FEATURE_SCHEMA_VERSION,
                raw_sha256=sha, raw_csv=str(source),
                primary_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),
                primary_rows=len(df), raw_rows=len(raw), source_review_passed=True,
                split_policy="pure_row_random_only", time_series_policy="all_measurements_preserved")
    (output / "dataset_manifest.json").write_text(json.dumps(info, indent=2), encoding="utf-8")
    return info


if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8")
    parser = argparse.ArgumentParser(description="Build the modeling table from the published dataset (single-file edition).")
    parser.add_argument("--source", type=Path, default=DEFAULT_SOURCE,
                        help=f"dataset CSV (default: {DEFAULT_SOURCE})")
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT,
                        help=f"output directory (default: {DEFAULT_OUTPUT})")
    args = parser.parse_args()
    print(json.dumps(prepare(args.source, args.output), indent=2, ensure_ascii=False))
